// Isolated prototype: crop a bounded PNG page raster, never transfer the original.
export const MAX_RASTER_BYTES=20*1024*1024,MAX_RASTER_PIXELS=16*1024*1024,MAX_CROP_BYTES=65536,MAX_PACKET_BYTES=100*1024;
const need=(v,m)=>{if(!v)throw Error(m);},sig=[137,80,78,71,13,10,26,10];
const exact=(v,k)=>need(v&&typeof v==='object'&&!Array.isArray(v)&&Object.keys(v).sort().join(',')===[...k].sort().join(','),'Unexpected crop fields');
const hash=v=>need(typeof v==='string'&&/^[a-f0-9]{64}$/.test(v),'Invalid digest reference');
const integer=(v,min,max)=>Number.isSafeInteger(v)&&v>=min&&v<=max;
export function rasterHeader(bytes){need(bytes instanceof Uint8Array&&bytes.length>=33&&sig.every((v,i)=>bytes[i]===v),'Choose a PNG page raster');const d=new DataView(bytes.buffer,bytes.byteOffset,bytes.byteLength);need(d.getUint32(8)===13&&String.fromCharCode(...bytes.slice(12,16))==='IHDR','Invalid PNG header');const width=d.getUint32(16),height=d.getUint32(20);need(integer(width,1,8192)&&integer(height,1,8192)&&width*height<=MAX_RASTER_PIXELS,'PNG exceeds the decoded page pixel limit');return {width,height};}
export function validateRegion(page,r){exact(r,['x','y','width','height']);need(integer(r.x,0,page.width-1)&&integer(r.y,0,page.height-1)&&integer(r.width,1,512)&&integer(r.height,1,512)&&r.width*r.height<=131072&&r.x+r.width<=page.width&&r.y+r.height<=page.height,'Choose an in-bounds crop no larger than 512 pixels per side and 131072 pixels total');need(r.width*r.height<=page.width*page.height/4,'Crop must cover at most one quarter of the page raster');return r;}
function crc(bytes){let n=0xffffffff;for(const b of bytes){n^=b;for(let i=0;i<8;i++)n=(n>>>1)^((n&1)?0xedb88320:0);}return (n^0xffffffff)>>>0;}
// Canvas output is decoded and re-encoded first; copy only essential PNG chunks.
export function cleanCanvasPng(bytes){rasterHeader(bytes);need(bytes.length<=MAX_CROP_BYTES,'Crop PNG exceeds 64 KiB; select a smaller region');const d=new DataView(bytes.buffer,bytes.byteOffset,bytes.byteLength),parts=[bytes.slice(0,8)];let pos=8,seenHeader=false,seenData=false,ended=false;
 while(pos<bytes.length){need(pos+12<=bytes.length,'Truncated PNG chunk');const size=d.getUint32(pos),end=pos+12+size;need(end<=bytes.length,'Truncated PNG payload');const type=String.fromCharCode(...bytes.slice(pos+4,pos+8));need(crc(bytes.slice(pos+4,end-4))===d.getUint32(end-4),'PNG chunk checksum mismatch');need(!ended,'Unexpected bytes after PNG end');
 if(type==='IHDR'){need(!seenHeader&&pos===8&&size===13,'Invalid PNG header order');seenHeader=true;need(bytes[pos+16]===8&&bytes[pos+17]===6&&bytes[pos+18]===0&&bytes[pos+19]===0&&bytes[pos+20]===0,'Use 8-bit non-interlaced RGBA canvas output');parts.push(bytes.slice(pos,end));}
 else if(type==='IDAT'){need(seenHeader,'PNG data before header');seenData=true;parts.push(bytes.slice(pos,end));}
 else if(type==='IEND'){need(seenData&&size===0,'Invalid PNG end');ended=true;parts.push(bytes.slice(pos,end));}
 else {need(type!=='acTL'&&type!=='fcTL'&&type!=='fdAT'&&/^[a-z]/.test(type),'Unsupported PNG chunk');}
 pos=end;
 }need(ended,'PNG end missing');const out=new Uint8Array(parts.reduce((n,p)=>n+p.length,0));let at=0;for(const p of parts){out.set(p,at);at+=p.length;}return out;
}
const sha=async bytes=>[...new Uint8Array(await crypto.subtle.digest('SHA-256',bytes))].map(v=>v.toString(16).padStart(2,'0')).join('');
const encode=bytes=>btoa(String.fromCharCode(...bytes));
function decode(s){need(typeof s==='string'&&s.length<=87384&&/^(?:[A-Za-z0-9+/]{4})*(?:[A-Za-z0-9+/]{2}==|[A-Za-z0-9+/]{3}=)?$/.test(s),'Invalid or oversized PNG encoding');const out=Uint8Array.from(atob(s),c=>c.charCodeAt(0));need(encode(out)===s,'Noncanonical PNG encoding');return out;}
export async function openPageRaster(file){need(file instanceof Blob&&file.size<=MAX_RASTER_BYTES,'Choose a local PNG page raster under 20 MiB; never a full document');const raw=new Uint8Array(await file.arrayBuffer()),header=rasterHeader(raw);const view=new DataView(raw.buffer);let offset=8;while(offset<raw.length){need(offset+12<=raw.length,'Truncated page PNG');const length=view.getUint32(offset),end=offset+length+12;need(end<=raw.length,'Truncated page PNG');const type=String.fromCharCode(...raw.slice(offset+4,offset+8));need(!['acTL','fcTL','fdAT'].includes(type),'Use a static PNG page, not an animation');offset=end;}const bitmap=await createImageBitmap(file);if(bitmap.width!==header.width||bitmap.height!==header.height){bitmap.close();throw Error('Decoded dimensions differ from header');}return {raw,header,bitmap};}
export async function createCrop(file,{region,correctionDigest,rightsAssertion}){region=structuredClone(region);hash(correctionDigest);need(typeof rightsAssertion==='string'&&rightsAssertion.trim()&&rightsAssertion.length<=2000,'Record the permission basis, without private information');const {raw,header,bitmap}=await openPageRaster(file);try{validateRegion(header,region);const canvas=document.createElement('canvas');canvas.width=region.width;canvas.height=region.height;const ctx=canvas.getContext('2d',{colorSpace:'srgb'});need(ctx,'Canvas unavailable');ctx.drawImage(bitmap,region.x,region.y,region.width,region.height,0,0,region.width,region.height);const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/png'));need(blob&&blob.size<=MAX_CROP_BYTES,'Crop PNG exceeds 64 KiB; select a smaller region');const png=cleanCanvasPng(new Uint8Array(await blob.arrayBuffer()));const crop={schema:'ocr.correction-crop.v1',correctionDigest,pageRaster:{sha256:await sha(raw),bytes:file.size,...header},region:{...region},processing:'browser-canvas-srgb-crop; essential PNG chunks only',rightsAssertion,image:{mime:'image/png',sha256:await sha(png),bytes:png.length,width:region.width,height:region.height,base64:encode(png)}};await validateCrop(crop);return crop;}finally{bitmap.close();}}
export async function validateCrop(c){exact(c,['schema','correctionDigest','pageRaster','region','processing','rightsAssertion','image']);need(c.schema==='ocr.correction-crop.v1'&&c.processing==='browser-canvas-srgb-crop; essential PNG chunks only','Unsupported crop processing');hash(c.correctionDigest);exact(c.pageRaster,['sha256','bytes','width','height']);hash(c.pageRaster.sha256);need(integer(c.pageRaster.bytes,33,MAX_RASTER_BYTES)&&integer(c.pageRaster.width,1,8192)&&integer(c.pageRaster.height,1,8192)&&c.pageRaster.width*c.pageRaster.height<=MAX_RASTER_PIXELS,'Invalid page raster reference');validateRegion(c.pageRaster,c.region);need(typeof c.rightsAssertion==='string'&&c.rightsAssertion.trim()&&c.rightsAssertion.length<=2000,'Missing permission assertion');exact(c.image,['mime','sha256','bytes','width','height','base64']);hash(c.image.sha256);need(c.image.mime==='image/png'&&c.image.width===c.region.width&&c.image.height===c.region.height&&integer(c.image.bytes,1,MAX_CROP_BYTES),'Invalid crop image');const png=decode(c.image.base64);need(png.length===c.image.bytes,'Crop byte count mismatch');const clean=cleanCanvasPng(png);need(clean.length===png.length,'Crop carries nonessential PNG metadata');const size=rasterHeader(png);need(size.width===c.image.width&&size.height===c.image.height,'Crop dimensions mismatch');need(await sha(png)===c.image.sha256,'Crop image digest mismatch');need(new TextEncoder().encode(JSON.stringify(c)).length<=MAX_PACKET_BYTES,'Crop packet exceeds 100 KiB');return c;}
// Stable canonical content covers region/provenance as well as image bytes. Not a signature.
function canonicalCrop(c){return JSON.stringify({schema:c.schema,correctionDigest:c.correctionDigest,pageRaster:{sha256:c.pageRaster.sha256,bytes:c.pageRaster.bytes,width:c.pageRaster.width,height:c.pageRaster.height},region:{x:c.region.x,y:c.region.y,width:c.region.width,height:c.region.height},processing:c.processing,rightsAssertion:c.rightsAssertion,image:{mime:c.image.mime,sha256:c.image.sha256,bytes:c.image.bytes,width:c.image.width,height:c.image.height,base64:c.image.base64}});}
export async function exportCrop(crop){const c=structuredClone(crop);await validateCrop(c);const raw=JSON.stringify({schema:'ocr.correction-crop-envelope.v1',crop:c,digest:await sha(new TextEncoder().encode(canonicalCrop(c)))},null,2);need(new TextEncoder().encode(raw).length<=MAX_PACKET_BYTES,'Crop packet exceeds 100 KiB');return raw;}
export async function importCrop(raw){need(typeof raw==='string'&&new TextEncoder().encode(raw).length<=MAX_PACKET_BYTES,'Choose a crop packet under 100 KiB');const p=JSON.parse(raw);if(p.schema==='ocr.correction-crop.v1')return validateCrop(p);exact(p,['schema','crop','digest']);need(p.schema==='ocr.correction-crop-envelope.v1','Unsupported crop envelope');hash(p.digest);await validateCrop(p.crop);need(await sha(new TextEncoder().encode(canonicalCrop(p.crop)))===p.digest,'Crop provenance digest mismatch');return p.crop;}


// Typed inspection for consumers: structural/digest checks are not image decoding.
// importCrop remains the compatibility API returning only the crop payload.
export async function inspectCropPacket(raw){const crop=await importCrop(raw),enveloped=JSON.parse(raw).schema==='ocr.correction-crop-envelope.v1';return {crop,checks:{pngStructure:'CHECKED',imageDigest:'CHECKED',provenanceDigest:enveloped?'CHECKED_UNSIGNED_ENVELOPE':'LEGACY_NOT_PRESENT',imageDecode:'NOT_PERFORMED',processingClaim:'UNVERIFIED',identity:'UNAUTHENTICATED',rights:'SELF_ASSERTED',admission:'NOT_PERFORMED'}};}
